def process_products(products: list, category: str) -> dict:
    filtered = [p for p in products if p['stock'] > 0 and p['category'] == category]

    if not filtered:
        return {'totalValue': 0, 'productNames': [], 'averagePrice': 0}

    total_value = sum(p['price'] * p['stock'] for p in filtered)
    product_names = [p['name'] for p in filtered]
    average_price = sum(p['price'] for p in filtered) / len(filtered)

    return {
        'totalValue': total_value,
        'productNames': product_names,
        'averagePrice': average_price
    }

solution.javascript:
function processProducts(products, category) {
    const filtered = products
        .filter(p => p.stock > 0 && p.category === category);

    if (filtered.length === 0) {
        return { totalValue: 0, productNames: [], averagePrice: 0 };
    }

    const totalValue = filtered
        .reduce((sum, p) => sum + p.price * p.stock, 0);

    const productNames = filtered
        .map(p => p.name);

    const averagePrice = filtered
        .reduce((sum, p) => sum + p.price, 0) / filtered.length;

    return { totalValue, productNames, averagePrice };
}
